import 'package:flutter_test/flutter_test.dart';

import 'package:aerend_customer/screens/bergen/sporing/leveringskode_card.dart';

/// Customer Step 2 (D-K17): the delivery-code QR is the design's own — the
/// modules the prototype's `kQrEkte` draws (version 3, level M, mask 0),
/// captured from the 21 Oct file with node for two payloads.
const Map<String, String> kDesignQr = {
    'https://aerend.no/k/42K-4831': '11111110000111001110001111111|10000010101100111001001000001|10111010000001101001101011101|10111010001011110001101011101|10111010111000100111101011101|10000010000011000111001000001|11111110101010101010101111111|00000000011111101111100000000|10101010001110110110000010010|01010001110000110110011001001|00101111110101000000010110111|00001101101000010100111000010|01000010001100001111111001011|11000000001011011010011001001|01100111110110111010011001011|01101100101101101100010101010|00010011100110110111101101011|00100100111100110110111001101|10000111100111000110010110011|01111001011000010110111001010|10011011100000001111111110000|00000000111111011111100010111|11111110000110111011101011011|10000010000111101111100011010|10111010100000110010111110010|10111010011000110000100110100|10111010111000000101000111001|10000010011101010001101000010|11111110111100101001100010011',
    'https://aerend.no/k/2AE-7723': '11111110010001001010001111111|10000010101110111111101000001|10111010001101101000101011101|10111010001011110001001011101|10111010110100100110001011101|10000010010001000111001000001|11111110101010101010101111111|00000000011011101110000000000|10101010010000110110000010010|00010101000100110110011001001|11111010101001000100010110111|11011100100110010110111000010|01100111001010001111111001011|10011100110001011110011001001|01000011011010111100011001011|11010001110001101110010101010|01010010010000110111101101011|00111000011100110110111001101|10010010010011000110010110011|01100100100010010100111001010|10100011100000001111111110000|00000000110111011111100010111|11111110000000111111101011011|10000010000101101111100011010|10111010111000110010111110010|10111010001001110000100110100|10111010101100000101000111001|10000010000000110001101000010|11111110101101101001100010011',
};

void main() {
  test('the QR modules match the design encoder (29 × 29, mask 0)', () {
    for (final e in kDesignQr.entries) {
      final m = LeveringskodeCard.moduler(e.key);
      expect(m.length, 29, reason: e.key);
      expect(m.map((r) => r.map((d) => d ? '1' : '0').join()).join('|'), e.value, reason: e.key);
    }
  });
}
